// ********************** GOOGLE CLOUD STORAGE **********************

/**
 * Optional service account resource, supplied on the classpath by the deployed runtime.
 * When it is absent the ambient (default) credentials of the runtime are used instead.
 */
public static final String GOOGLE_SERVICE_ACCOUNT_RESOURCE = "google-cloud-service-account.json"
public static final String DEFAULT_GOOGLE_CLOUD_STORAGE_BUCKET_NAME = "bank-connect-documents"

public static String fetchGoogleCloudStorageBucketName() {
    String bucketName = null
    try {
        def flatConfig = Holders.getFlatConfig()
        bucketName = flatConfig?.get("google.storage.bucket.name")?.toString() ?: flatConfig?.get("grails.google.storage.bucket.name")?.toString()
    } catch (Exception e) {
        log.warn("Unable to read Google Cloud Storage bucket name from configuration ==>> ${e.message}")
    }
    if (StringUtils.isBlank(bucketName))
        bucketName = System.getenv("GOOGLE_STORAGE_BUCKET_NAME")
    StringUtils.isNotBlank(bucketName) ? bucketName : DEFAULT_GOOGLE_CLOUD_STORAGE_BUCKET_NAME
}

public static Storage fetchGoogleCloudStorageService() {
    Storage storage = null
    InputStream credentialsStream = null
    try {
        ClassLoader classLoader = HelperMethod.class.getClassLoader() ?: Thread.currentThread().getContextClassLoader()
        credentialsStream = classLoader?.getResourceAsStream(GOOGLE_SERVICE_ACCOUNT_RESOURCE)
        if (credentialsStream) {
            //Credentials are loaded reflectively so that the auth library remains an optional, runtime only concern
            def credentials = Class.forName("com.google.auth.oauth2.ServiceAccountCredentials").fromStream(credentialsStream)
            storage = StorageOptions.newBuilder().setCredentials(credentials).build().getService()
        }
    } catch (Exception e) {
        log.error("Exception while building Google Cloud Storage service from the classpath service account ==>> ${e.message}", e)
        storage = null
    } finally {
        try {
            credentialsStream?.close()
        } catch (Exception ignored) {
        }
    }
    if (storage == null) {
        log.info("=== Using ambient credentials for Google Cloud Storage ===")
        storage = StorageOptions.getDefaultInstance()?.getService()
    }
    storage
}

public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (file && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = fetchGoogleCloudStorageService()
            BlobInfo blobInfo = BlobInfo.newBuilder(BlobId.of(fetchGoogleCloudStorageBucketName(), path)).build()
            storage.create(blobInfo, file.getBytes())
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
    InputStream inputStream = null
    if (StringUtils.isNotBlank(path)) {
        try {
            Storage storage = fetchGoogleCloudStorageService()
            BlobId blobId = BlobId.of(fetchGoogleCloudStorageBucketName(), path)
            byte[] content = null
            try {
                def blob = storage.get(blobId)
                content = blob?.getContent()
            } catch (Exception e) {
                log.warn("Unable to read blob '${path}' from Google Cloud Storage ==>> ${e.message}")
            }
            if (content == null) {
                try {
                    content = storage.readAllBytes(blobId)
                } catch (Exception e) {
                    log.warn("Unable to read bytes of '${path}' from Google Cloud Storage ==>> ${e.message}")
                }
            }
            if (content != null)
                inputStream = new ByteArrayInputStream(content)
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

public static Boolean deleteObjectFromGoogleCloudStorage(String path) {
    Boolean isFileDeleted = Boolean.FALSE
    if (StringUtils.isNotBlank(path)) {
        try {
            Storage storage = fetchGoogleCloudStorageService()
            storage.delete(BlobId.of(fetchGoogleCloudStorageBucketName(), path))
            isFileDeleted = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while deleting file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileDeleted
}

public static void uploadObjectToLocalOrGoogleCloudStorage(File pdfFile, String documentPath = null) {
    if (GrailsUtil.developmentEnv) {
        log.info("=== Requesting file to be uploaded on Local location ===>>> ${documentPath}")
        File file = new File(documentPath)
        FileUtils.writeByteArrayToFile(file, pdfFile.getBytes())
    } else {
        log.info("=== Requesting file to be uploaded on Google Cloud Storage location ===>>> ${documentPath}")
        uploadObjectToGoogleCloudStorage(pdfFile, documentPath)
    }
}

